import{_ as s,o as t,c as a,a2 as n}from"./chunks/framework.CdvW4CUT.js";const u=JSON.parse('{"title":"How it fits together","description":"","frontmatter":{},"headers":[],"relativePath":"reference/architecture.md","filePath":"reference/architecture.md","lastUpdated":1793092343000}'),o={name:"reference/architecture.md"};function i(r,e,p,l,c,h){return t(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="how-it-fits-together" tabindex="-1">How it fits together <a class="header-anchor" href="#how-it-fits-together" aria-label="Permalink to &quot;How it fits together&quot;">​</a></h1><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Tablet (Fully Kiosk Browser or the Android app) ── https://&lt;site&gt; (Caddy on the server, ideally home network only)</span></span>
<span class="line"><span>  │  Svelte app: clock, weather, room buttons, animated face</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ├─ Home Assistant WebSocket (a non-admin token, from the welcome or the tablet&#39;s settings)</span></span>
<span class="line"><span>  │    pipeline &quot;Frog Hub · &lt;Personality&gt;&quot;: openWakeWord (&quot;hey jarvis&quot;) → Whisper → … → Piper voice</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ├─ /api/ask → the Frog Hub server (127.0.0.1:8790) → the brain</span></span>
<span class="line"><span>  │    Claude Code: Haiku in its own session (~/froghub-agent: its own CLAUDE.md and memory, no shell, no other MCP servers)</span></span>
<span class="line"><span>  │    or the API brain: the Anthropic API and/or an OpenAI-compatible one</span></span>
<span class="line"><span>  │    replies with text and optional actions, which the display runs only for devices in its room</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  └─ /tts/* → Home Assistant&#39;s tts_proxy (same origin, so the app can pitch-shift each personality&#39;s voice)</span></span></code></pre></div><ul><li><strong>The display</strong> is a web app (Svelte). It talks to Home Assistant directly, with its own token, for the voice and the room&#39;s devices, and to the Frog Hub server for everything else. The server never needs a Home Assistant token.</li><li><strong>The server</strong> (<code>channel/</code>) serves the <a href="/reference/http-api">HTTP API</a> and the assistant&#39;s tools, and keeps alarms, announcements, schedules, the displays&#39; registry and the settings in <code>~/.config/froghub/</code>.</li><li><strong>The brain</strong> answers. With Claude Code, the server is an MCP channel of a long-running Claude Code session, which replies through a <code>reply</code> tool. With the API brain (<code>channel/standalone.ts</code>), the server calls the model itself. The display can&#39;t tell the difference.</li><li><strong>The voice</strong> runs in three containers (<code>setup/voice/compose.yaml</code>, Wyoming protocol): openWakeWord on 10400, Whisper on 10300 and Piper on 10200, used by Home Assistant&#39;s pipelines.</li></ul><h2 id="a-request-step-by-step" tabindex="-1">A request, step by step <a class="header-anchor" href="#a-request-step-by-step" aria-label="Permalink to &quot;A request, step by step&quot;">​</a></h2><ol><li>Wake word and speech-to-text: one pipeline run (<code>wake_word</code> → <code>stt</code>), audio streamed as 16 kHz PCM.</li><li>The answer: <code>POST /api/ask</code> with the text, personality, speaker&#39;s name and the room&#39;s devices.</li><li>Speech: a second pipeline run (<code>tts</code> only) with the personality&#39;s Piper voice, played back at its <code>pitch</code>.</li></ol>`,5)])])}const m=s(o,[["render",i]]);export{u as __pageData,m as default};
